1	//! [`BashTool`] — a shell tool that runs commands through a pluggable
2	//! [`ExecutionBackend`]. The tool itself only parses arguments and applies the
3	//! command allow/deny lists; *containment* is the backend's job (and is reported
4	//! in this tool's description via the backend's `guarantees()`).
5	
6	use std::marker::PhantomData;
7	use std::sync::Arc;
8	
9	use async_trait::async_trait;
10	use paigasus_helikon_core::{Tool, ToolContext, ToolEffect, ToolError, ToolOutput};
11	use serde::Deserialize;
12	use serde_json::Value;
13	
14	use crate::exec::{ExecRequest, ExecutionBackend};
15	
16	/// Arguments for [`BashTool`].
17	#[derive(Debug, Deserialize, schemars::JsonSchema)]
18	struct BashArgs {
19	    /// The shell command to run (`sh -c <command>` on unix, `cmd /C` on Windows).
20	    command: String,
21	}
22	
23	/// Builder for [`BashTool`]. Obtain one via [`BashTool::builder`].
24	pub struct BashToolBuilder {
25	    backend: Arc<dyn ExecutionBackend>,
26	    deny_commands: Vec<String>,
27	    allow_commands: Option<Vec<String>>,
28	}
29	
30	impl BashToolBuilder {
31	    /// Refuse any command whose first whitespace-delimited token is in this list.
32	    pub fn deny_commands<I, S>(mut self, names: I) -> Self
33	    where
34	        I: IntoIterator<Item = S>,
35	        S: Into<String>,
36	    {
37	        self.deny_commands = names.into_iter().map(Into::into).collect();
38	        self
39	    }
40	
41	    /// If set, allow ONLY commands whose first token is in this list.
42	    pub fn allow_commands<I, S>(mut self, names: I) -> Self
43	    where
44	        I: IntoIterator<Item = S>,
45	        S: Into<String>,
46	    {
47	        self.allow_commands = Some(names.into_iter().map(Into::into).collect());
48	        self
49	    }
50	
51	    /// Finish building.
52	    pub fn build<Ctx>(self) -> BashTool<Ctx> {
53	        let label = self.backend.guarantees().label;
54	        let description = format!(
55	            "Run a shell command. Containment tier: {label}. The working directory \
56	             is pinned to the sandbox root. The actual enforcement depends on the \
57	             configured backend (see the containment tier above); gate access with \
58	             a PermissionPolicy or DenyRule(\"Bash\") as needed."
59	        );
60	        BashTool {
61	            backend: self.backend,
62	            deny_commands: self.deny_commands,
63	            allow_commands: self.allow_commands,
64	            description,
65	            schema: serde_json::to_value(schemars::schema_for!(BashArgs))
66	                .expect("BashArgs schema serializes"),
67	            _ctx: PhantomData,
68	        }
69	    }
70	}
71	
72	/// A shell tool backed by a pluggable [`ExecutionBackend`].
73	pub struct BashTool<Ctx = ()> {
74	    backend: Arc<dyn ExecutionBackend>,
75	    deny_commands: Vec<String>,
76	    allow_commands: Option<Vec<String>>,
77	    description: String,
78	    schema: Value,
79	    _ctx: PhantomData<fn() -> Ctx>,
80	}
81	
82	impl BashTool<()> {
83	    /// Start building a `BashTool` over `backend`.
84	    pub fn builder(backend: Arc<dyn ExecutionBackend>) -> BashToolBuilder {
85	        BashToolBuilder {
86	            backend,
87	            deny_commands: Vec::new(),
88	            allow_commands: None,
89	        }
90	    }
91	
92	    /// Build a `BashTool` over `backend` with no command allow/deny lists.
93	    pub fn new(backend: Arc<dyn ExecutionBackend>) -> BashTool<()> {
94	        Self::builder(backend).build()
95	    }
96	}
97	
98	impl<Ctx> BashTool<Ctx> {
99	    fn check_command_allowed(&self, command: &str) -> Result<(), ToolError> {
100	        let first = command.split_whitespace().next().unwrap_or("");
101	        if self.deny_commands.iter().any(|d| d == first) {
102	            return Err(ToolError::Denied {
103	                reason: format!("command `{first}` is blocked by the deny list"),
104	            });
105	        }
106	        if let Some(allow) = &self.allow_commands {
107	            if !allow.iter().any(|a| a == first) {
108	                return Err(ToolError::Denied {
109	                    reason: format!("command `{first}` is not in the allow list"),
110	                });
111	            }
112	        }
113	        Ok(())
114	    }
115	}
116	
117	#[async_trait]
118	impl<Ctx> Tool<Ctx> for BashTool<Ctx>
119	where
120	    Ctx: Send + Sync + 'static,
121	{
122	    fn name(&self) -> &str {
123	        "Bash"
124	    }
125	
126	    fn description(&self) -> &str {
127	        &self.description
128	    }
129	
130	    fn schema(&self) -> &Value {
131	        &self.schema
132	    }
133	
134	    fn effect(&self) -> ToolEffect {
135	        ToolEffect::SideEffect
136	    }
137	
138	    async fn invoke(&self, _ctx: &ToolContext<Ctx>, args: Value) -> Result<ToolOutput, ToolError> {
139	        let args: BashArgs = serde_json::from_value(args).map_err(|e| ToolError::InvalidArgs {
140	            schema_errors: vec![e.to_string()],
141	        })?;
142	        self.check_command_allowed(&args.command)?;
143	        let out = self.backend.run(ExecRequest::new(args.command)).await?;
144	        Ok(ToolOutput::new(serde_json::json!({
145	            "stdout": out.stdout,
146	            "stderr": out.stderr,
147	            "exit_code": out.exit_code,
148	            "timed_out": out.timed_out,
149	            "truncated": out.truncated,
150	        })))
151	    }
152	}
