1	//! Permission layer: gate tool calls via deny rules → permission mode →
2	//! `canUseTool` policy. See the *Permissions, Guardrails & Hooks* concept page.
3	
4	use async_trait::async_trait;
5	
6	use crate::RunContext;
7	
8	/// How permission mode governs tool calls.
9	///
10	/// `Bypass` propagates to subagents and **cannot be overridden** — a typed
11	/// enum, not a string. The non-override property is enforced by
12	/// [`RunContext::with_permission_mode`], which refuses to downgrade `Bypass`.
13	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
14	#[non_exhaustive]
15	pub enum PermissionMode {
16	    /// Defer to the policy (ask for unfamiliar tools); permissive when no policy.
17	    #[default]
18	    Default,
19	    /// Auto-approve tools with a [`crate::ToolEffect::Write`] effect; all other
20	    /// tools still reach the policy.
21	    AcceptEdits,
22	    /// Read-only: deny any tool whose [`crate::ToolEffect`] is not `ReadOnly`.
23	    Plan,
24	    /// Dangerous: allow all (deny rules still apply). Propagates; sticky.
25	    Bypass,
26	}
27	
28	/// The outcome of a [`PermissionPolicy::check`] (or the resolved decision).
29	#[derive(Debug, Clone)]
30	#[non_exhaustive]
31	pub enum PermissionDecision {
32	    /// Run the call unchanged.
33	    Allow,
34	    /// Block the call; the reason is surfaced to the model as a tool result.
35	    Deny {
36	        /// Human-readable denial reason.
37	        reason: String,
38	    },
39	    /// Ask a human (resolved via [`ApprovalHandler`]; default Deny).
40	    AskUser {
41	        /// Prompt shown to the approver.
42	        prompt: String,
43	    },
44	    /// Replace the call's arguments before execution (sanitize).
45	    Replace {
46	        /// Replacement JSON arguments.
47	        args: serde_json::Value,
48	    },
49	}
50	
51	/// Authorizes a tool call. The decision pipeline runs
52	/// `deny rules › mode › this policy` (see `control.rs`).
53	#[async_trait]
54	pub trait PermissionPolicy<Ctx>: Send + Sync
55	where
56	    Ctx: Send + Sync + 'static,
57	{
58	    /// Decide whether `tool` may run with `args`.
59	    async fn check(
60	        &self,
61	        ctx: &RunContext<Ctx>,
62	        tool: &str,
63	        args: &serde_json::Value,
64	    ) -> PermissionDecision;
65	}
66	
67	/// A first-class deny rule, evaluated **before** mode — so it overrides even
68	/// [`PermissionMode::Bypass`]. v1 matches by exact tool name.
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	pub struct DenyRule {
71	    tool: String,
72	}
73	
74	impl DenyRule {
75	    /// Deny a tool by its exact name.
76	    pub fn tool(name: impl Into<String>) -> Self {
77	        Self { tool: name.into() }
78	    }
79	
80	    /// `true` if this rule denies `tool`. `_args` is reserved for richer
81	    /// (arg-aware) matchers in a later ticket.
82	    pub fn matches(&self, tool: &str, _args: &serde_json::Value) -> bool {
83	        self.tool == tool
84	    }
85	}
86	
87	/// Resolves a [`PermissionDecision::AskUser`] when the driver cannot decide
88	/// inline. Non-generic — it needs no `Ctx`.
89	#[async_trait]
90	pub trait ApprovalHandler: Send + Sync {
91	    /// Decide an `AskUser` prompt. Returns a narrowed [`ApprovalOutcome`]
92	    /// (cannot recursively ask).
93	    async fn decide(&self, tool: &str, prompt: &str, args: &serde_json::Value) -> ApprovalOutcome;
94	}
95	
96	/// The narrowed decision an [`ApprovalHandler`] may return.
97	#[derive(Debug, Clone)]
98	#[non_exhaustive]
99	pub enum ApprovalOutcome {
100	    /// Allow the call.
101	    Allow,
102	    /// Deny the call with a reason.
103	    Deny {
104	        /// Human-readable denial reason.
105	        reason: String,
106	    },
107	}
108	
109	#[cfg(test)]
110	mod tests {
111	    use super::*;
112	    use serde_json::json;
113	
114	    #[test]
115	    fn permission_mode_default_is_default_variant() {
116	        assert_eq!(PermissionMode::default(), PermissionMode::Default);
117	    }
118	
119	    #[test]
120	    fn deny_rule_matches_exact_tool_name_only() {
121	        let rule = DenyRule::tool("rm");
122	        assert!(rule.matches("rm", &json!({})));
123	        assert!(!rule.matches("ls", &json!({})));
124	        assert!(rule.matches("rm", &json!({"path": "/etc/passwd"})));
125	    }
126	}
