1	//! `Interceptors`: the run's control-layer orchestration unit.
2	//!
3	//! Borrows the stream-local Arc-snapshots of the agent's guardrails/hooks and
4	//! the run's [`RunContext`] (mode, policy, deny rules, approval handler). The
5	//! driver calls its async methods at the loop's control seams. Pure of the
6	//! state machine — all async control lives here, not in `transition()`.
7	
8	use std::sync::Arc;
9	
10	use crate::{
11	    ApprovalOutcome, Guardrail, Hook, HookDecision, HookEvent, HookRegistry, PermissionDecision,
12	    PermissionMode, RunContext, ToolEffect,
13	};
14	
15	/// Borrows everything the control seams need for one run.
16	pub(crate) struct Interceptors<'a, Ctx>
17	where
18	    Ctx: Send + Sync + 'static,
19	{
20	    pub(crate) ctx: &'a RunContext<Ctx>,
21	    pub(crate) input_guardrails: &'a [Arc<dyn Guardrail<Ctx>>],
22	    pub(crate) output_guardrails: &'a [Arc<dyn Guardrail<Ctx>>],
23	    pub(crate) agent_hooks: &'a [Arc<dyn Hook<Ctx>>],
24	}
25	
26	/// The folded outcome of firing all hooks for one event.
27	#[derive(Debug, Default)]
28	pub(crate) struct ResolvedHookDecision {
29	    /// `Some(reason)` if any hook denied (first wins).
30	    pub(crate) denied: Option<String>,
31	    /// The last `ReplaceInput`/`ReplaceOutput` value, if any.
32	    pub(crate) replacement: Option<serde_json::Value>,
33	    /// All injected system messages, in fire order.
34	    pub(crate) injections: Vec<String>,
35	}
36	
37	impl<'a, Ctx> Interceptors<'a, Ctx>
38	where
39	    Ctx: Send + Sync + 'static,
40	{
41	    /// Fire `event` to agent-level hooks first, then the run-level
42	    /// [`HookRegistry`]. Folds outcomes: first `Deny` short-circuits;
43	    /// `Replace*` last-writer-wins; `InjectSystemMessage` accumulates.
44	    pub(crate) async fn fire(&self, event: &HookEvent) -> ResolvedHookDecision {
45	        let mut out = ResolvedHookDecision::default();
46	        let registry: &HookRegistry<Ctx> = self.ctx.hooks();
47	        let all = self.agent_hooks.iter().chain(registry.iter());
48	        for hook in all {
49	            match hook.on_event(self.ctx, event).await {
50	                HookDecision::Allow => {}
51	                HookDecision::Deny { reason } => {
52	                    out.denied = Some(reason);
53	                    return out; // short-circuit
54	                }
55	                HookDecision::ReplaceInput { value } | HookDecision::ReplaceOutput { value } => {
56	                    out.replacement = Some(value);
57	                }
58	                HookDecision::InjectSystemMessage { text } => {
59	                    out.injections.push(text);
60	                }
61	            }
62	        }
63	        out
64	    }
65	
66	    /// Run input guardrails as a blocking gate. Returns `Some((kind, info))`
67	    /// on the first tripwire, else `None`. A guardrail's own error is treated
68	    /// as a tripwire with [`crate::GuardrailKind::Other`].
69	    pub(crate) async fn run_input_guardrails(
70	        &self,
71	        text: &str,
72	    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
73	        self.run_guardrails(self.input_guardrails, crate::GuardrailInput::UserText(text))
74	            .await
75	    }
76	
77	    /// Run output guardrails as a blocking gate on the final text.
78	    pub(crate) async fn run_output_guardrails(
79	        &self,
80	        text: &str,
81	    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
82	        self.run_guardrails(
83	            self.output_guardrails,
84	            crate::GuardrailInput::ModelOutput(text),
85	        )
86	        .await
87	    }
88	
89	    async fn run_guardrails(
90	        &self,
91	        guardrails: &[Arc<dyn Guardrail<Ctx>>],
92	        input: crate::GuardrailInput<'_>,
93	    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
94	        for g in guardrails {
95	            match g.check(self.ctx, input.clone()).await {
96	                Ok(crate::GuardrailVerdict::Pass) => {}
97	                Ok(crate::GuardrailVerdict::Tripwire { kind, info }) => return Some((kind, info)),
98	                Err(e) => {
99	                    return Some((
100	                        crate::GuardrailKind::Other {
101	                            reason: e.to_string(),
102	                        },
103	                        serde_json::Value::Null,
104	                    ))
105	                }
106	            }
107	        }
108	        None
109	    }
110	
111	    /// Authorize one tool call on its effective args: `deny rules › mode ›
112	    /// policy › AskUser`. Returns the resolved decision (never `AskUser` — that
113	    /// is resolved here via the approval handler, default Deny).
114	    pub(crate) async fn authorize(
115	        &self,
116	        tool: &str,
117	        effect: ToolEffect,
118	        args: &serde_json::Value,
119	    ) -> PermissionDecision {
120	        // 1. Deny rules — absolute, override even Bypass.
121	        if self.ctx.deny_rules().iter().any(|r| r.matches(tool, args)) {
122	            return PermissionDecision::Deny {
123	                reason: format!("denied by deny rule: {tool}"),
124	            };
125	        }
126	        // 2. Mode.
127	        match self.ctx.permission_mode() {
128	            PermissionMode::Bypass => return PermissionDecision::Allow,
129	            PermissionMode::Plan if effect != ToolEffect::ReadOnly => {
130	                return PermissionDecision::Deny {
131	                    reason: format!("Plan mode forbids the side-effecting tool `{tool}`"),
132	                };
133	            }
134	            PermissionMode::AcceptEdits if effect == ToolEffect::Write => {
135	                return PermissionDecision::Allow;
136	            }
137	            _ => {}
138	        }
139	        // 3. Policy (canUseTool). None ⇒ permissive.
140	        let decision = match self.ctx.permission_policy() {
141	            None => return PermissionDecision::Allow,
142	            Some(policy) => policy.check(self.ctx, tool, args).await,
143	        };
144	        // 4. AskUser ⇒ approval handler; None ⇒ Deny.
145	        match decision {
146	            PermissionDecision::AskUser { prompt } => match self.ctx.approval_handler() {
147	                None => PermissionDecision::Deny {
148	                    reason: "no approval handler installed".to_owned(),
149	                },
150	                Some(handler) => match handler.decide(tool, &prompt, args).await {
151	                    ApprovalOutcome::Allow => PermissionDecision::Allow,
152	                    ApprovalOutcome::Deny { reason } => PermissionDecision::Deny { reason },
153	                },
154	            },
155	            other => other,
156	        }
157	    }
158	}
