1	//! The [`Tool`] trait and its carrier types.
2	//!
3	//! Tools are object-safe by design — applications hold heterogeneous
4	//! registries as `Vec<Arc<dyn Tool<Ctx>>>`.
5	
6	use std::sync::Arc;
7	
8	use async_trait::async_trait;
9	
10	use crate::{
11	    ActionsHandle, ApprovalHandler, CancellationToken, DenyRule, HookRegistry, PermissionMode,
12	    PermissionPolicy, SessionState, TracerHandle,
13	};
14	
15	/// A tool's side-effect profile. Drives [`crate::PermissionMode`] decisions:
16	/// `Plan` allows only `ReadOnly`; `AcceptEdits` auto-approves `Write`.
17	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
18	#[non_exhaustive]
19	pub enum ToolEffect {
20	    /// No side effects; safe to run under `Plan` mode.
21	    ReadOnly,
22	    /// Mutates local/filesystem state; auto-approved by `AcceptEdits`.
23	    Write,
24	    /// Any other side effect (network, external). Safe-by-default.
25	    #[default]
26	    SideEffect,
27	}
28	
29	/// A tool an agent can call.
30	///
31	/// Object-safe by design — applications hold heterogeneous registries as
32	/// `Vec<Arc<dyn Tool<Ctx>>>`.
33	///
34	/// # Example
35	///
36	/// ```
37	/// use async_trait::async_trait;
38	/// use paigasus_helikon_core::{Tool, ToolContext, ToolError, ToolOutput};
39	/// use serde_json::{json, Value};
40	///
41	/// struct EchoTool {
42	///     schema: Value,
43	/// }
44	///
45	/// #[async_trait]
46	/// impl Tool<()> for EchoTool {
47	///     fn name(&self) -> &str { "echo" }
48	///     fn description(&self) -> &str { "Returns the input verbatim." }
49	///     fn schema(&self) -> &Value { &self.schema }
50	///
51	///     async fn invoke(
52	///         &self,
53	///         _ctx: &ToolContext<()>,
54	///         args: Value,
55	///     ) -> Result<ToolOutput, ToolError> {
56	///         Ok(ToolOutput::new(args))
57	///     }
58	/// }
59	///
60	/// let _tool = EchoTool {
61	///     schema: json!({ "type": "object" }),
62	/// };
63	/// ```
64	#[async_trait]
65	pub trait Tool<Ctx>: Send + Sync
66	where
67	    Ctx: Send + Sync + 'static,
68	{
69	    /// Tool name, unique per registry. Used by the model to address calls.
70	    fn name(&self) -> &str;
71	    /// Human-readable description, shown to the model.
72	    fn description(&self) -> &str;
73	    /// JSON Schema for the argument payload.
74	    fn schema(&self) -> &serde_json::Value;
75	    /// Optional JSON Schema for the return payload. Default is `None`.
76	    fn output_schema(&self) -> Option<&serde_json::Value> {
77	        None
78	    }
79	
80	    /// This tool's side-effect profile. Default [`ToolEffect::SideEffect`]
81	    /// (safe-by-default): an undeclared tool is treated as side-effecting, so
82	    /// `Plan` mode blocks it.
83	    fn effect(&self) -> ToolEffect {
84	        ToolEffect::SideEffect
85	    }
86	
87	    /// Execute the tool with `args` (a JSON value matching [`Tool::schema`]).
88	    async fn invoke(
89	        &self,
90	        ctx: &ToolContext<Ctx>,
91	        args: serde_json::Value,
92	    ) -> Result<ToolOutput, ToolError>;
93	}
94	
95	/// Narrower view of [`crate::RunContext`] passed to [`Tool::invoke`].
96	///
97	/// Deliberately excludes the session handle: tools must not bypass the
98	/// runner's persistence by writing directly to the session log. The run-level
99	/// hook registry rides along as a `pub(crate)` carrier (used only by
100	/// `agent_as_tool` to fire `OnSubagentStop`); it is **not** exposed to `Tool`
101	/// impls — hooks fire *around* tool invocations, not from inside them.
102	pub struct ToolContext<Ctx>
103	where
104	    Ctx: Send + Sync + 'static,
105	{
106	    user_ctx: Arc<Ctx>,
107	    tracer: TracerHandle,
108	    cancel: CancellationToken,
109	    agent_depth: u32,
110	    max_agent_depth: u32,
111	    state: SessionState,
112	    actions: ActionsHandle,
113	    /// Carrier for the parent run's [`HookRegistry`], projected by
114	    /// [`crate::RunContext::to_tool_context`]. `pub(crate)` — read only by the
115	    /// `agent_as_tool` path to fire `OnSubagentStop`; not exposed to tools.
116	    pub(crate) hooks: HookRegistry<Ctx>,
117	    permission_mode: PermissionMode,
118	    // read by agent_as_tool in a later task
119	    pub(crate) permission_policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
120	    // read by agent_as_tool in a later task
121	    pub(crate) deny_rules: Vec<DenyRule>,
122	    // read by agent_as_tool in a later task
123	    pub(crate) approval_handler: Option<Arc<dyn ApprovalHandler>>,
124	}
125	
126	impl<Ctx> ToolContext<Ctx>
127	where
128	    Ctx: Send + Sync + 'static,
129	{
130	    /// Construct a new [`ToolContext`].
131	    pub fn new(
132	        user_ctx: Arc<Ctx>,
133	        tracer: TracerHandle,
134	        cancel: CancellationToken,
135	        agent_depth: u32,
136	        max_agent_depth: u32,
137	    ) -> Self {
138	        Self {
139	            user_ctx,
140	            tracer,
141	            cancel,
142	            agent_depth,
143	            max_agent_depth,
144	            state: SessionState::new(),
145	            actions: ActionsHandle::new(),
146	            hooks: HookRegistry::new(),
147	            permission_mode: PermissionMode::Default,
148	            permission_policy: None,
149	            deny_rules: Vec::new(),
150	            approval_handler: None,
151	        }
152	    }
153	
154	    /// Borrow the user context.
155	    pub fn user_ctx(&self) -> &Arc<Ctx> {
156	        &self.user_ctx
157	    }
158	    /// Borrow the tracer handle.
159	    pub fn tracer(&self) -> &TracerHandle {
160	        &self.tracer
161	    }
162	    /// Borrow the cancellation token.
163	    pub fn cancel(&self) -> &CancellationToken {
164	        &self.cancel
165	    }
166	    /// Current agent-nesting depth (handoff + agent-as-tool). `AgentAsTool`
167	    /// reads this to bound recursion.
168	    pub fn agent_depth(&self) -> u32 {
169	        self.agent_depth
170	    }
171	    /// The configured maximum agent-nesting depth (from `RunConfig`, or the
172	    /// default when no runner installed a config).
173	    pub fn max_agent_depth(&self) -> u32 {
174	        self.max_agent_depth
175	    }
176	    /// Borrow the run-scoped [`SessionState`] shared across sub-agents.
177	    pub fn state(&self) -> &SessionState {
178	        &self.state
179	    }
180	    /// Borrow the [`ActionsHandle`]. A tool calls `ctx.actions().escalate()`
181	    /// to stop an enclosing [`crate::LoopAgent`].
182	    pub fn actions(&self) -> &ActionsHandle {
183	        &self.actions
184	    }
185	    /// Install the shared [`SessionState`] (used by
186	    /// [`crate::RunContext::to_tool_context`]).
187	    pub fn with_state(mut self, state: SessionState) -> Self {
188	        self.state = state;
189	        self
190	    }
191	    /// Install the [`ActionsHandle`] (used by
192	    /// [`crate::RunContext::to_tool_context`]).
193	    pub fn with_actions(mut self, actions: ActionsHandle) -> Self {
194	        self.actions = actions;
195	        self
196	    }
197	
198	    /// Install the run-level hook registry (used by
199	    /// [`crate::RunContext::to_tool_context`]). `pub(crate)` — read only by the
200	    /// `agent_as_tool` path to fire `OnSubagentStop`; not exposed to tools.
201	    pub(crate) fn with_hooks(mut self, hooks: HookRegistry<Ctx>) -> Self {
202	        self.hooks = hooks;
203	        self
204	    }
205	
206	    /// The run's permission mode. A tool may legitimately branch on this.
207	    pub fn permission_mode(&self) -> PermissionMode {
208	        self.permission_mode
209	    }
210	
211	    /// Install the permission config (used by [`crate::RunContext::to_tool_context`]).
212	    /// `policy`/`deny_rules`/`handler` are `pub(crate)` carriers read only by
213	    /// the `agent_as_tool` rebuild path — not exposed to tools.
214	    pub(crate) fn with_permissions(
215	        mut self,
216	        mode: PermissionMode,
217	        policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
218	        deny_rules: Vec<DenyRule>,
219	        handler: Option<Arc<dyn ApprovalHandler>>,
220	    ) -> Self {
221	        self.permission_mode = mode;
222	        self.permission_policy = policy;
223	        self.deny_rules = deny_rules;
224	        self.approval_handler = handler;
225	        self
226	    }
227	}
228	
229	/// The result of a successful [`Tool::invoke`] call.
230	///
231	/// Field shape (multi-modal content, metadata) lands with later tickets.
232	/// Today `content` is the raw JSON value the tool returned.
233	#[derive(Debug, Clone, Default)]
234	#[non_exhaustive]
235	pub struct ToolOutput {
236	    /// The tool's return payload, as JSON.
237	    pub content: serde_json::Value,
238	}
239	
240	impl ToolOutput {
241	    /// Construct a [`ToolOutput`] with the given JSON content.
242	    pub fn new(content: serde_json::Value) -> Self {
243	        Self { content }
244	    }
245	}
246	
247	/// Errors raised by [`Tool::invoke`].
248	///
249	/// `InvalidArgs` is the single recoverable variant per ADR-10: the runner
250	/// is permitted to feed the schema errors back to the model once before
251	/// surfacing [`crate::AgentError::InvalidStructuredOutput`]. No other
252	/// variant is recoverable.
253	#[derive(Debug, thiserror::Error)]
254	#[non_exhaustive]
255	pub enum ToolError {
256	    /// Arguments did not match [`Tool::schema`].
257	    ///
258	    /// Recoverable per ADR-10 — the runner may feed `schema_errors` back to
259	    /// the model once before surfacing
260	    /// [`crate::AgentError::InvalidStructuredOutput`].
261	    #[error("invalid tool arguments: {schema_errors:?}")]
262	    InvalidArgs {
263	        /// Human-readable schema-validation errors.
264	        schema_errors: Vec<String>,
265	    },
266	
267	    /// The tool refused the operation: either a hard safety-boundary violation
268	    /// (a path outside the sandbox root, a non-UTF-8 read) or an unsatisfiable
269	    /// precondition (an ambiguous edit target, an allow/deny-blocked command).
270	    /// Distinct from a [`crate::PermissionPolicy`] denial, which the runner
271	    /// resolves before `invoke` is ever called. Not recoverable.
272	    #[error("operation denied: {reason}")]
273	    Denied {
274	        /// Human-readable denial reason, surfaced to the model.
275	        reason: String,
276	    },
277	
278	    /// Escape hatch for arbitrary tool failures. See ADR-10.
279	    #[error(transparent)]
280	    Other(#[from] anyhow::Error),
281	}
