1	//! Run-scoped context types.
2	//!
3	//! [`RunContext`] carries user data, session handle, hook registry, tracer,
4	//! and cancellation token across the agent loop.
5	
6	use std::sync::Arc;
7	
8	use crate::{
9	    ActionsHandle, ApprovalHandler, DenyRule, FailureSlot, Hook, PermissionMode, PermissionPolicy,
10	    RunConfig, Session, SessionState, ToolContext,
11	};
12	
13	/// Carries the per-run state shared across the agent loop, tools,
14	/// guardrails, and hooks.
15	///
16	/// `RunContext` does **not** implement `Default` — a context without a
17	/// session handle is meaningless. Construct via [`RunContext::new`].
18	///
19	/// # Example
20	///
21	/// ```
22	/// use std::sync::Arc;
23	/// use async_trait::async_trait;
24	/// use paigasus_helikon_core::{
25	///     CancellationToken, ConversationSnapshot, HookRegistry, RunContext,
26	///     SequenceId, Session, SessionError, SessionEvent, TracerHandle,
27	/// };
28	///
29	/// struct NoopSession;
30	/// #[async_trait]
31	/// impl Session for NoopSession {
32	///     async fn append(&self, _: &[SessionEvent]) -> Result<(), SessionError> { Ok(()) }
33	///     async fn events(&self, _: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
34	///         Ok(Vec::new())
35	///     }
36	///     async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
37	///         Ok(ConversationSnapshot::default())
38	///     }
39	/// }
40	///
41	/// let _ctx: RunContext<()> = RunContext::new(
42	///     Arc::new(()),
43	///     Arc::new(NoopSession),
44	///     HookRegistry::<()>::new(),
45	///     TracerHandle::default(),
46	///     CancellationToken::new(),
47	/// );
48	/// ```
49	pub struct RunContext<Ctx>
50	where
51	    Ctx: Send + Sync + 'static,
52	{
53	    user_ctx: Arc<Ctx>,
54	    session: Arc<dyn Session>,
55	    hooks: HookRegistry<Ctx>,
56	    tracer: TracerHandle,
57	    cancel: CancellationToken,
58	    /// Per-invocation execution policy, injected by a `Runner` (e.g.
59	    /// `TokioRunner`). This is the runner-injection channel, **not** general
60	    /// context state: it is deliberately NOT surfaced into [`ToolContext`] by
61	    /// [`RunContext::to_tool_context`]. `None` when an agent is run directly
62	    /// without a runner.
63	    run_config: Option<RunConfig>,
64	    /// Out-of-band carrier for the run's terminal structured [`crate::AgentError`].
65	    /// Written by [`crate::Agent::run`] at the moment of failure; read at the
66	    /// boundary by a [`crate::Runner`] / [`crate::RunResultStreaming`]. Like
67	    /// `run_config`, it is **not** projected into [`ToolContext`].
68	    failure: FailureSlot,
69	    /// Agent-nesting depth: 0 for a top-level run, incremented by
70	    /// [`RunContext::handoff_child`] and by `AgentAsTool` for each nested
71	    /// agent run. Bounded by [`crate::RunConfig::max_agent_depth`].
72	    agent_depth: u32,
73	    /// Run-scoped coordination KV shared across sub-agents (SMA-325). Shared by
74	    /// `subagent_child` / `handoff_child`; **not** projected as isolated.
75	    state: SessionState,
76	    /// Control side-channel a tool writes (e.g. `escalate`). A **fresh** handle
77	    /// per `subagent_child`, so a `LoopAgent` reads only the current sub-run's signal.
78	    actions: ActionsHandle,
79	    /// How the permission layer governs tool calls for this run.
80	    /// Monotonic on `Bypass`: once set, it cannot be downgraded.
81	    permission_mode: PermissionMode,
82	    /// Optional `canUseTool` policy, evaluated after deny rules and mode.
83	    permission_policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
84	    /// Deny rules evaluated before mode (override even `Bypass`).
85	    deny_rules: Vec<DenyRule>,
86	    /// Resolves `AskUser` decisions; `None` → deny by default.
87	    approval_handler: Option<Arc<dyn ApprovalHandler>>,
88	}
89	
90	impl<Ctx> RunContext<Ctx>
91	where
92	    Ctx: Send + Sync + 'static,
93	{
94	    /// Construct a new [`RunContext`].
95	    pub fn new(
96	        user_ctx: Arc<Ctx>,
97	        session: Arc<dyn Session>,
98	        hooks: HookRegistry<Ctx>,
99	        tracer: TracerHandle,
100	        cancel: CancellationToken,
101	    ) -> Self {
102	        Self {
103	            user_ctx,
104	            session,
105	            hooks,
106	            tracer,
107	            cancel,
108	            run_config: None,
109	            failure: FailureSlot::new(),
110	            agent_depth: 0,
111	            state: SessionState::new(),
112	            actions: ActionsHandle::new(),
113	            permission_mode: PermissionMode::Default,
114	            permission_policy: None,
115	            deny_rules: Vec::new(),
116	            approval_handler: None,
117	        }
118	    }
119	
120	    /// Borrow the user context.
121	    pub fn user_ctx(&self) -> &Arc<Ctx> {
122	        &self.user_ctx
123	    }
124	    /// Borrow the session handle.
125	    pub fn session(&self) -> &Arc<dyn Session> {
126	        &self.session
127	    }
128	    /// Borrow the hook registry.
129	    pub fn hooks(&self) -> &HookRegistry<Ctx> {
130	        &self.hooks
131	    }
132	    /// Borrow the tracer handle.
133	    pub fn tracer(&self) -> &TracerHandle {
134	        &self.tracer
135	    }
136	    /// Borrow the cancellation token.
137	    pub fn cancel(&self) -> &CancellationToken {
138	        &self.cancel
139	    }
140	
141	    /// Borrow the run-scoped [`SessionState`] shared across sub-agents.
142	    pub fn state(&self) -> &SessionState {
143	        &self.state
144	    }
145	    /// Borrow the [`ActionsHandle`] for this (sub-)run.
146	    pub fn actions(&self) -> &ActionsHandle {
147	        &self.actions
148	    }
149	
150	    /// Borrow the per-invocation [`RunConfig`], if a runner installed one.
151	    pub fn run_config(&self) -> Option<&RunConfig> {
152	        self.run_config.as_ref()
153	    }
154	
155	    /// Clone the handle to this run's [`FailureSlot`].
156	    ///
157	    /// A [`crate::Runner`] clones this **before** moving the context into
158	    /// [`crate::Agent::run`] (the same way it clones `cancel` / `session`), then
159	    /// reads the structured error after the run's event stream drains.
160	    pub fn failure_handle(&self) -> FailureSlot {
161	        self.failure.clone()
162	    }
163	
164	    /// Nesting depth that produced this context (0 at top level).
165	    pub fn agent_depth(&self) -> u32 {
166	        self.agent_depth
167	    }
168	
169	    /// Stamp an explicit nesting depth. Used by `AgentAsTool` when it builds
170	    /// the isolated sub-context for its wrapped agent.
171	    pub fn with_agent_depth(mut self, depth: u32) -> Self {
172	        self.agent_depth = depth;
173	        self
174	    }
175	
176	    /// Install the run-scoped [`SessionState`]. Used by `AgentAsTool` to build
177	    /// the fire-only context for `OnSubagentStop` so hooks observe the parent's
178	    /// shared `state` rather than a fresh one.
179	    pub(crate) fn with_state(mut self, state: SessionState) -> Self {
180	        self.state = state;
181	        self
182	    }
183	
184	    /// A context for a handed-off sub-run. A handoff *continues the same
185	    /// logical run*, so the child **shares** session, hooks, cancel token,
186	    /// failure slot, and run config (including per-invocation limits like
187	    /// `max_turns` / `timeout`) — with `agent_depth` incremented by one.
188	    /// (Distinct from `AgentAsTool`, which builds an isolated context.)
189	    ///
190	    /// The increment saturates: depth is bounded far below `u32::MAX` by the
191	    /// driver's `max_agent_depth` guard, so saturating is purely defensive.
192	    pub fn handoff_child(&self) -> Self {
193	        Self {
194	            user_ctx: Arc::clone(&self.user_ctx),
195	            session: Arc::clone(&self.session),
196	            hooks: self.hooks.clone(),
197	            tracer: self.tracer.clone(),
198	            cancel: self.cancel.clone(),
199	            run_config: self.run_config.clone(),
200	            failure: self.failure.clone(),
201	            agent_depth: self.agent_depth.saturating_add(1),
202	            state: self.state.clone(),
203	            actions: self.actions.clone(),
204	            permission_mode: self.permission_mode,
205	            permission_policy: self.permission_policy.clone(),
206	            deny_rules: self.deny_rules.clone(),
207	            approval_handler: self.approval_handler.clone(),
208	        }
209	    }
210	
211	    /// A context for one sub-agent of a workflow agent (`SequentialAgent`,
212	    /// `ParallelAgent`, `LoopAgent`). **Shares** the run-scoped `state`, session,
213	    /// cancel token, tracer, user context, and run config; gets a **fresh**
214	    /// `FailureSlot` and a **fresh** `ActionsHandle` (so the workflow agent reads
215	    /// only this sub-run's failure / escalate); `agent_depth` incremented by one.
216	    pub fn subagent_child(&self) -> Self {
217	        Self {
218	            user_ctx: Arc::clone(&self.user_ctx),
219	            session: Arc::clone(&self.session),
220	            hooks: self.hooks.clone(),
221	            tracer: self.tracer.clone(),
222	            cancel: self.cancel.clone(),
223	            run_config: self.run_config.clone(),
224	            failure: FailureSlot::new(),
225	            agent_depth: self.agent_depth.saturating_add(1),
226	            state: self.state.clone(),
227	            actions: ActionsHandle::new(),
228	            permission_mode: self.permission_mode,
229	            permission_policy: self.permission_policy.clone(),
230	            deny_rules: self.deny_rules.clone(),
231	            approval_handler: self.approval_handler.clone(),
232	        }
233	    }
234	
235	    /// Install the per-invocation [`RunConfig`] (consuming builder). A
236	    /// [`crate::Runner`] calls this before [`crate::Agent::run`].
237	    pub fn with_run_config(mut self, config: RunConfig) -> Self {
238	        self.run_config = Some(config);
239	        self
240	    }
241	
242	    /// Set the permission mode. **Monotonic on `Bypass`:** once the mode is
243	    /// `Bypass`, this is a no-op — `Bypass` cannot be downgraded (the safety
244	    /// invariant). All other transitions apply.
245	    pub fn with_permission_mode(mut self, mode: PermissionMode) -> Self {
246	        if self.permission_mode != PermissionMode::Bypass {
247	            self.permission_mode = mode;
248	        }
249	        self
250	    }
251	
252	    /// Install the run's permission policy (`canUseTool`).
253	    pub fn with_permission_policy(mut self, policy: Arc<dyn PermissionPolicy<Ctx>>) -> Self {
254	        self.permission_policy = Some(policy);
255	        self
256	    }
257	
258	    /// Install deny rules, evaluated before mode (override even `Bypass`).
259	    pub fn with_deny_rules(mut self, rules: Vec<DenyRule>) -> Self {
260	        self.deny_rules = rules;
261	        self
262	    }
263	
264	    /// Install the approval handler that resolves `AskUser` decisions.
265	    pub fn with_approval_handler(mut self, handler: Arc<dyn ApprovalHandler>) -> Self {
266	        self.approval_handler = Some(handler);
267	        self
268	    }
269	
270	    /// The current permission mode.
271	    pub fn permission_mode(&self) -> PermissionMode {
272	        self.permission_mode
273	    }
274	
275	    /// The run's permission policy, if installed.
276	    pub fn permission_policy(&self) -> Option<&Arc<dyn PermissionPolicy<Ctx>>> {
277	        self.permission_policy.as_ref()
278	    }
279	
280	    /// The run's deny rules.
281	    pub fn deny_rules(&self) -> &[DenyRule] {
282	        &self.deny_rules
283	    }
284	
285	    /// The run's approval handler, if installed.
286	    pub fn approval_handler(&self) -> Option<&Arc<dyn ApprovalHandler>> {
287	        self.approval_handler.as_ref()
288	    }
289	
290	    /// Project the narrower [`ToolContext`] from this [`RunContext`].
291	    ///
292	    /// Tools receive `user_ctx`, `tracer`, and a **child** cancellation
293	    /// token. The child observes the parent's cancellation but tool-side
294	    /// `cancel()` calls only cancel the tool's subtree — they do not
295	    /// propagate back to the run.
296	    ///
297	    /// Tools do not see the session handle (the runner owns persistence). The
298	    /// run-level hook registry is projected as a `pub(crate)` carrier (for
299	    /// `agent_as_tool` to fire `OnSubagentStop`), but is not exposed to `Tool`
300	    /// impls — hooks fire around tool invocations, not from inside.
301	    pub fn to_tool_context(&self) -> ToolContext<Ctx> {
302	        let max_agent_depth = self
303	            .run_config
304	            .as_ref()
305	            .map(|c| c.max_agent_depth)
306	            .unwrap_or_else(|| RunConfig::default().max_agent_depth);
307	        ToolContext::new(
308	            Arc::clone(&self.user_ctx),
309	            self.tracer.clone(),
310	            self.cancel.child_token(),
311	            self.agent_depth,
312	            max_agent_depth,
313	        )
314	        .with_state(self.state.clone())
315	        .with_actions(self.actions.clone())
316	        .with_hooks(self.hooks.clone())
317	        .with_permissions(
318	            self.permission_mode,
319	            self.permission_policy.clone(),
320	            self.deny_rules.clone(),
321	            self.approval_handler.clone(),
322	        )
323	    }
324	}
