558	/// Registry of hooks active for one run.
559	///
560	/// Today the surface is intentionally minimal — just `new`, `push`,
561	/// `iter`, and `is_empty`. The agent-loop ticket grows this when it
562	/// needs per-event filtering.
563	pub struct HookRegistry<Ctx>
564	where
565	    Ctx: Send + Sync + 'static,
566	{
567	    hooks: Vec<Arc<dyn Hook<Ctx>>>,
568	}
569	
570	impl<Ctx> HookRegistry<Ctx>
571	where
572	    Ctx: Send + Sync + 'static,
573	{
574	    /// Construct an empty registry.
575	    pub fn new() -> Self {
576	        Self { hooks: Vec::new() }
577	    }
578	
579	    /// Register a hook.
580	    pub fn push(&mut self, hook: Arc<dyn Hook<Ctx>>) {
581	        self.hooks.push(hook);
582	    }
583	
584	    /// Iterate over registered hooks in registration order.
585	    pub fn iter(&self) -> impl Iterator<Item = &Arc<dyn Hook<Ctx>>> {
586	        self.hooks.iter()
587	    }
588	
589	    /// `true` if no hooks are registered.
590	    pub fn is_empty(&self) -> bool {
591	        self.hooks.is_empty()
592	    }
593	}
594	
595	impl<Ctx> Default for HookRegistry<Ctx>
596	where
597	    Ctx: Send + Sync + 'static,
598	{
599	    fn default() -> Self {
600	        Self::new()
601	    }
602	}
603	
604	impl<Ctx> Clone for HookRegistry<Ctx>
605	where
606	    Ctx: Send + Sync + 'static,
607	{
608	    fn clone(&self) -> Self {
609	        Self {
610	            hooks: self.hooks.clone(),
611	        }
612	    }
613	}
