615	/// Carrier for per-run trace-level attributes (Langfuse `session.id` /
616	/// `user.id` / `tags`) that the agent loop stamps onto the run and turn
617	/// spans. Construct an empty handle with [`TracerHandle::default`] or a
618	/// populated one via [`TracerHandle::builder`].
619	#[derive(Debug, Clone, Default)]
620	pub struct TracerHandle {
621	    session_id: Option<String>,
622	    user_id: Option<String>,
623	    tags: Vec<String>,
624	}
625	
626	impl TracerHandle {
627	    /// Start building a populated handle.
628	    pub fn builder() -> TracerHandleBuilder {
629	        TracerHandleBuilder::default()
630	    }
631	
632	    /// Langfuse session id, if set.
633	    pub fn session_id(&self) -> Option<&str> {
634	        self.session_id.as_deref()
635	    }
636	
637	    /// Langfuse user id, if set.
638	    pub fn user_id(&self) -> Option<&str> {
639	        self.user_id.as_deref()
640	    }
641	
642	    /// Langfuse trace tags (possibly empty).
643	    pub fn tags(&self) -> &[String] {
644	        &self.tags
645	    }
646	}
647	
648	/// Consuming builder for [`TracerHandle`].
649	#[derive(Debug, Default)]
650	pub struct TracerHandleBuilder {
651	    session_id: Option<String>,
652	    user_id: Option<String>,
653	    tags: Vec<String>,
654	}
655	
656	impl TracerHandleBuilder {
657	    /// Set the Langfuse session id.
658	    pub fn with_session_id(mut self, id: impl Into<String>) -> Self {
659	        self.session_id = Some(id.into());
660	        self
661	    }
662	
663	    /// Set the Langfuse user id.
664	    pub fn with_user_id(mut self, id: impl Into<String>) -> Self {
665	        self.user_id = Some(id.into());
666	        self
667	    }
668	
669	    /// Append one Langfuse trace tag.
670	    pub fn with_tag(mut self, tag: impl Into<String>) -> Self {
671	        self.tags.push(tag.into());
672	        self
673	    }
674	
675	    /// Finish building the [`TracerHandle`].
676	    pub fn build(self) -> TracerHandle {
677	        TracerHandle {
678	            session_id: self.session_id,
679	            user_id: self.user_id,
680	            tags: self.tags,
681	        }
682	    }
683	}
